O.renderPublicForm=async function(formId){var app=document.getElementById('app');if(!app)return;app.innerHTML='<main class="ops-public"><div class="ops-public-loading">جارٍ تحميل النموذج…</div></main>';try{var pub=await O.rpc('public_organization_form',{p_form_id:formId}),org=pub.organization,f=pub.form,c=f.config||{},fields=c.fields||[];var extra=fields.map(function(x){var type=['number','date','email','tel'].indexOf(x.type)>=0?x.type:'text';return '<label>'+O.esc(x.label)+'<input data-public-extra="'+O.esc(x.key)+'" type="'+type+'" '+(x.required?'required':'')+'></label>'}).join('');app.innerHTML='<main class="ops-public"><header><b>Play<span>In</span><small>365</small></b><a href="'+location.origin+location.pathname+'">تسجيل الدخول</a></header><section class="ops-public-hero"><span>PUBLIC FORM</span><h1>'+O.esc(f.name)+'</h1><p>'+O.esc(c.description||org.name_ar||org.name_en)+'</p></section><section class="ops-public-form"><div><span>'+O.esc(org.name_ar||org.name_en)+'</span><h2>أرسل بياناتك</h2><p>تصل الإجابة إلى صندوق النماذج داخل الأكاديمية.</p></div><div class="ops-form cols-2"><label>الاسم الكامل<input id="publicDynamicName" autocomplete="name" required></label>'+(c.require_phone!==false?'<label>رقم الجوال<input id="publicDynamicPhone" inputmode="tel" autocomplete="tel"></label>':'')+(c.require_email?'<label>البريد<input id="publicDynamicEmail" type="email" autocomplete="email"></label>':'')+extra+'<div class="ops-form-action">'+O.btn('إرسال','ACOPS.submitPublicDynamicForm(\''+formId+'\',this)','primary')+'</div></div></section><footer>PlayIn365 · نموذج آمن للأكاديمية</footer></main>';document.body.classList.add('ops-public-body')}catch(e){console.error(e);app.innerHTML='<main class="ops-public"><div class="ops-empty"><b>النموذج غير متاح</b><span>قد يكون متوقفًا أو انتهت صلاحيته.</span><a class="ops-btn primary" href="'+location.origin+location.pathname+'">العودة</a></div></main>'}};
O.submitPublicDynamicForm=async function(formId,btn){var old=btn.innerHTML;btn.disabled=true;btn.innerHTML='جارٍ الإرسال…';try{var payload={};document.querySelectorAll('[data-public-extra]').forEach(function(x){payload[x.getAttribute('data-public-extra')]=x.value});var r=await O.rpc('submit_public_organization_form',{p_form_id:formId,p_name:O.val('publicDynamicName'),p_phone:O.val('publicDynamicPhone')||null,p_email:O.val('publicDynamicEmail')||null,p_payload:payload});O.toast('تم إرسال النموذج');document.querySelectorAll('.ops-public-form input').forEach(function(x){x.value=''})}catch(e){O.toast(O.errorText(e),1)}finally{btn.disabled=false;btn.innerHTML=old}};

